begin;
select no_plan();
select ok(to_regclass('social_private.settings') is not null,'social storage exists');
select ok(bool_and(relrowsecurity),'all twelve social tables enable RLS') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='social_private' and relkind='r';
select is(count(*)::integer,12,'exact private table inventory') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='social_private' and relkind='r';
select ok(not exists(select from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join(values('anon'),('authenticated'),('gmaiden_iam_runtime')) roles(role) where n.nspname='social_private' and c.relkind='r' and has_table_privilege(roles.role,c.oid,'SELECT,INSERT,UPDATE,DELETE')),'no direct social grants');
select ok(not has_table_privilege('gmaiden_iam_runtime','auth.sessions','SELECT') and not has_table_privilege('gmaiden_iam_runtime','public.profiles','SELECT'),'runtime cannot read sessions/contact/Steam profile rows');
select ok(not exists(select from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='social_private' and p.proname not in('action','redeem') and has_function_privilege('gmaiden_iam_runtime',p.oid,'EXECUTE')),'runtime cannot invoke helpers or operator functions');
select ok(not exists(select from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='social_private' and(not p.prosecdef or not p.proconfig @> array['search_path=""'])),'all private routines are fixed-search-path definers');
insert into auth.users(id) select md5(n::text)::uuid from generate_series(1,1200)n;
insert into auth.sessions select md5('s'||n)::uuid,md5(n::text)::uuid from generate_series(1,1200)n;
insert into public.profiles(id,gid_code,display_name) select md5(n::text)::uuid,'G-TEST'||n,'Person '||n from generate_series(1,1200)n;
create function pg_temp.call(n integer,b jsonb,h text default null,p jsonb default null) returns jsonb language sql as $$ select social_private.action(md5(n::text)::uuid,md5('s'||n)::uuid,b,'https://relay.example.test',p,h) $$;
grant execute on function pg_temp.call(integer,jsonb,text,jsonb) to gmaiden_iam_runtime;
set local role gmaiden_iam_runtime;
select is(current_user,'gmaiden_iam_runtime','behavior tests use restricted runtime');
select is(pg_temp.call(1,'{"action":"state"}')->'settings','{"presenceVisible":false,"allowFriendRequests":true,"allowInvites":true}'::jsonb,'hidden by default');
select is(pg_temp.call(1,'{"action":"request","gid":"G-TEST1"}')->>'error','invalid_request','self request denied');
select is(pg_temp.call(1,'{"action":"request","gid":"G-TEST2"}'),' {"ok":true}'::jsonb,'live Google AAL1 actor can request');
select is(pg_temp.call(2,'{"action":"request","gid":"G-TEST1"}'),' {"ok":true}'::jsonb,'reciprocal stays pending');
select is(jsonb_array_length(pg_temp.call(1,'{"action":"state"}')->'friends'),0,'reciprocal did not autoaccept');
reset role;
select is((select count(*)::integer from social_private.requests),1,'canonical request unique');
select id as request_id from social_private.requests \gset
set local role gmaiden_iam_runtime;
select is(pg_temp.call(1,jsonb_build_object('action','request_accept','requestId',:'request_id'))->>'error','forbidden','sender cannot accept');
select is(pg_temp.call(2,jsonb_build_object('action','request_accept','requestId',:'request_id')),'{"ok":true}'::jsonb,'recipient accepts');
select is(pg_temp.call(2,jsonb_build_object('action','request_accept','requestId',:'request_id')),'{"ok":true}'::jsonb,'duplicate acceptance is idempotent');
select is(pg_temp.call(2,'{"action":"heartbeat"}'),' {"ok":true}'::jsonb,'hidden heartbeat no lease');
reset role;
select is((select count(*)::integer from social_private.presence),0,'no hidden lease persisted');
set local role gmaiden_iam_runtime;
select pg_temp.call(2,'{"action":"settings","presenceVisible":true,"allowFriendRequests":true,"allowInvites":true}');
select pg_temp.call(2,'{"action":"heartbeat"}');
select is(pg_temp.call(1,'{"action":"state"}')->'friends'->0->>'online','true','visible live Google presence projects online');
reset role;
select ok((select expires_at<=clock_timestamp()+interval '60 seconds' and expires_at>clock_timestamp()+interval '59 seconds' from social_private.presence),'presence lease exactly sixty seconds maximum');
update social_private.presence set expires_at=clock_timestamp();
set local role gmaiden_iam_runtime;
select is(pg_temp.call(1,'{"action":"state"}')->'friends'->0->>'online','false','exclusive expiry offline at sixty seconds');
select pg_temp.call(2,'{"action":"heartbeat"}');
select pg_temp.call(2,'{"action":"settings","presenceVisible":false,"allowFriendRequests":true,"allowInvites":true}');
reset role;
select is((select count(*)::integer from social_private.presence),0,'hide synchronously deletes all leases');
insert into social_private.presence values(md5('2')::uuid,md5('s2')::uuid,clock_timestamp()+interval '60 seconds');
delete from auth.sessions where id=md5('s2')::uuid;
select is((select count(*)::integer from social_private.presence),0,'session revoke cascades lease');
set local role gmaiden_iam_runtime;
select is(pg_temp.call(2,'{"action":"heartbeat"}')->>'error','invalid_session','revoked actor denied');
select is(pg_temp.call(3,'{"action":"request","gid":"G-NONE"}')->>'error','unavailable','unknown GID same unavailable');
select pg_temp.call(3,'{"action":"request","gid":"G-NONE"}') from generate_series(1,9);
select is(pg_temp.call(3,'{"action":"request","gid":"G-NONE"}')->>'error','rate_limited','ten expected denials consume rate budget');
reset role;
insert into auth.sessions values(md5('s2')::uuid,md5('2')::uuid);
-- Request cap is combined incoming/outgoing and checked at both accounts.
insert into social_private.requests(sender,recipient,expires_at) select md5('4')::uuid,md5(n::text)::uuid,clock_timestamp()+interval '30 days' from generate_series(10,59)n;
set local role gmaiden_iam_runtime;
select is(pg_temp.call(5,'{"action":"request","gid":"G-TEST4"}')->>'error','limit_reached','combined request cap fifty');
reset role;
insert into social_private.friendships select least(md5('6')::uuid,md5(n::text)::uuid),greatest(md5('6')::uuid,md5(n::text)::uuid) from generate_series(100,299)n;
insert into social_private.requests(sender,recipient,expires_at) values(md5('7')::uuid,md5('6')::uuid,clock_timestamp()+interval '30 days') returning id as cap_id \gset
set local role gmaiden_iam_runtime;
select is(pg_temp.call(6,jsonb_build_object('action','request_accept','requestId',:'cap_id'))->>'error','limit_reached','friend cap two hundred');
reset role;
insert into social_private.blocks select md5('8')::uuid,md5(n::text)::uuid from generate_series(400,899)n;
set local role gmaiden_iam_runtime;
select is(pg_temp.call(8,'{"action":"block","gid":"G-TEST900"}')->>'error','limit_reached','block cap five hundred');
select is(pg_temp.call(8,'{"action":"unblock","gid":"G-TEST400"}'),' {"ok":true}'::jsonb,'unblock works at capacity');
select pg_temp.call(1,'{"action":"block","gid":"G-TEST2"}');
select is(pg_temp.call(2,'{"action":"request","gid":"G-TEST1"}')->>'error','unavailable','blocked pair same unavailable');
select pg_temp.call(1,'{"action":"unblock","gid":"G-TEST2"}');
select is(jsonb_array_length(pg_temp.call(1,'{"action":"state"}')->'friends'),0,'unblock does not restore friendship');
select pg_temp.call(9,'{"action":"settings","presenceVisible":false,"allowFriendRequests":false,"allowInvites":false}');
select is(pg_temp.call(2,'{"action":"request","gid":"G-TEST9"}')->>'error','unavailable','disabled requests same unavailable');
-- Link revision, challenge single use, purpose/session binding and consent renewal.
select pg_temp.call(1,'{"action":"challenge","purpose":"link","recipientGid":null,"bindingRevision":0}',repeat('a',64));
select pg_temp.call(1,'{"action":"unlink"}');
select is(pg_temp.call(1,'{"action":"challenge","purpose":"link","recipientGid":null,"bindingRevision":0}',repeat('b',64))->>'error','conflict','delayed pre-unlink mint cannot revive old intent');
select is(pg_temp.call(1,'{"action":"state"}')->>'bindingRevision','1','unlink acknowledges advanced revision');
reset role;
select is((select count(*)::integer from social_private.challenges where session_id=md5('s1')::uuid),0,'unlink deletes outstanding link challenges');
set local role gmaiden_iam_runtime;
select pg_temp.call(1,'{"action":"challenge","purpose":"link","recipientGid":null,"bindingRevision":1}',repeat('c',64));
select jsonb_build_object('roomId',repeat('2',32),'memberId',repeat('3',32),'ownerId',repeat('3',32),'generation',1,'memberIds',jsonb_build_array(repeat('3',32)),'expiresAtMs',floor(extract(epoch from clock_timestamp()+interval '60 seconds')*1000)) as proof \gset
select is(pg_temp.call(1,'{"action":"link","bindingRevision":1,"consent":false}',repeat('c',64),:'proof')->>'error','consent_required','renewal cannot create initial link');
select is(pg_temp.call(1,'{"action":"link","bindingRevision":1,"consent":true}',repeat('c',64),:'proof')->>'error','unavailable','denied consumption still one use');
select pg_temp.call(1,'{"action":"challenge","purpose":"link","recipientGid":null,"bindingRevision":1}',repeat('d',64));
select is(pg_temp.call(1,'{"action":"link","bindingRevision":1,"consent":true}',repeat('d',64),:'proof'),' {"ok":true}'::jsonb,'explicit fresh consent binds member');
select pg_temp.call(1,'{"action":"challenge","purpose":"roster","recipientGid":null,"bindingRevision":null}',repeat('e',64));
select is(jsonb_array_length(pg_temp.call(1,'{"action":"roster"}',repeat('e',64),:'proof')->'bindings'),1,'roster projects current explicit binding');
reset role;
-- Invite transaction and nonce accounting.
insert into social_private.friendships values(least(md5('1')::uuid,md5('2')::uuid),greatest(md5('1')::uuid,md5('2')::uuid));
set local role gmaiden_iam_runtime;
select pg_temp.call(1,'{"action":"challenge","purpose":"invite","recipientGid":"G-TEST2","bindingRevision":null}',repeat('f',64));
select is(pg_temp.call(1,'{"action":"invite"}',repeat('f',64),:'proof'),' {"ok":true}'::jsonb,'owner proof creates targeted invite');
reset role;
select ok((select expires_at<=clock_timestamp()+interval '300 seconds' and expires_at>clock_timestamp()+interval '299 seconds' from social_private.invites),'invitation lease three hundred seconds');
select id as invite_id from social_private.invites \gset
set local role gmaiden_iam_runtime;
select is(pg_temp.call(1,jsonb_build_object('action','invite_accept','inviteId',:'invite_id','consent',true),repeat('1',64))->>'error','forbidden','sender cannot accept invite');
select ok(pg_temp.call(2,jsonb_build_object('action','invite_accept','inviteId',:'invite_id','consent',true),repeat('1',64)) ? 'roomId','recipient accepts');
select is(social_private.redeem(repeat('9',64),repeat('8',64),'https://relay.example.test')->>'error','unavailable','invalid ticket burns authenticated nonce');
select is(social_private.redeem(repeat('1',64),repeat('8',64),'https://relay.example.test')->>'error','unavailable','same nonce cannot try different valid ticket');
select ok(social_private.redeem(repeat('1',64),repeat('7',64),'https://relay.example.test') ? 'roomId','fresh nonce consumes valid ticket');
select is(social_private.redeem(repeat('1',64),repeat('6',64),'https://relay.example.test')->>'error','unavailable','ticket one use');
reset role;
select is((select count(*)::integer from social_private.join_tickets),0,'redeemed ticket removed immediately');
select is((select count(*)::integer from social_private.invites),0,'redeemed invite removed immediately');
insert into social_private.presence values(md5('1')::uuid,md5('s1')::uuid,clock_timestamp()-interval '1 second');
select ok(social_private.cleanup()>0,'bounded maintenance removes expired ephemeral rows');
delete from auth.users where id=md5('1')::uuid;
select is((select count(*)::integer from social_private.room_bindings where user_id=md5('1')::uuid),0,'account deletion cascades bindings');
select is((select count(*)::integer from social_private.friendships where a=md5('1')::uuid or b=md5('1')::uuid),0,'account deletion cascades relationships');
-- Remaining capacities and direction checks, with fresh independent actors.
set local role gmaiden_iam_runtime;
select pg_temp.call(20,'{"action":"challenge","purpose":"roster","recipientGid":null,"bindingRevision":null}',lpad(n::text,64,'0')) from generate_series(1,4)n;
select is(pg_temp.call(20,'{"action":"challenge","purpose":"roster","recipientGid":null,"bindingRevision":null}',repeat('9',64))->>'error','limit_reached','four live challenges per session');
reset role;
select is((select count(*)::integer from social_private.challenges where user_id=md5('20')::uuid),4,'rejected mint does not persist extra challenge');
update social_private.challenges set expires_at=clock_timestamp() where user_id=md5('20')::uuid;
set local role gmaiden_iam_runtime;
select ok(pg_temp.call(20,'{"action":"challenge","purpose":"roster","recipientGid":null,"bindingRevision":null}',repeat('9',64)) ? 'expiresAtMs','expired challenges cease counting immediately');
reset role;
update auth.users set raw_app_meta_data='{"provider":"email"}' where id=md5('21')::uuid;
set local role gmaiden_iam_runtime;
select is(pg_temp.call(21,'{"action":"state"}')->>'error','invalid_session','SQL independently requires Google provider');
reset role;
insert into social_private.requests(sender,recipient,expires_at) values(md5('22')::uuid,md5('23')::uuid,clock_timestamp()+interval '30 days') returning id as direction_id \gset
set local role gmaiden_iam_runtime;
select is(pg_temp.call(22,jsonb_build_object('action','request_decline','requestId',:'direction_id'))->>'error','forbidden','only recipient declines');
select is(pg_temp.call(23,jsonb_build_object('action','request_cancel','requestId',:'direction_id'))->>'error','forbidden','only sender cancels');
select is(pg_temp.call(22,jsonb_build_object('action','request_cancel','requestId',:'direction_id')),'{"ok":true}'::jsonb,'sender cancellation succeeds');
reset role;
-- A verified proof cannot change the challenge account, session or purpose.
insert into auth.sessions values(md5('second22')::uuid,md5('22')::uuid);
set local role gmaiden_iam_runtime;
select pg_temp.call(22,'{"action":"challenge","purpose":"link","recipientGid":null,"bindingRevision":0}',repeat('5',64));
select is(social_private.action(md5('22')::uuid,md5('second22')::uuid,'{"action":"link","bindingRevision":0,"consent":true}','https://relay.example.test',:'proof',repeat('5',64))->>'error','unavailable','cross-session proof rejected');
select is(pg_temp.call(23,'{"action":"link","bindingRevision":0,"consent":true}',repeat('5',64),:'proof')->>'error','unavailable','cross-account proof rejected');
select is(pg_temp.call(22,'{"action":"roster"}',repeat('5',64),:'proof')->>'error','unavailable','cross-purpose proof rejected');
reset role;
-- Invite disabling, removing and blocking cancel both pending and accepted tickets.
insert into social_private.friendships values(least(md5('24')::uuid,md5('25')::uuid),greatest(md5('24')::uuid,md5('25')::uuid));
insert into social_private.invites(sender,sender_session,recipient,recipient_session,relay_origin,room_id,owner_id,member_id,generation,status,expires_at) values(md5('24')::uuid,md5('s24')::uuid,md5('25')::uuid,md5('s25')::uuid,'https://relay.example.test',repeat('2',32),repeat('3',32),repeat('3',32),1,'accepted',clock_timestamp()+interval '300 seconds') returning id as remove_invite \gset
insert into social_private.join_tickets values(repeat('4',64),:'remove_invite',clock_timestamp()+interval '60 seconds');
set local role gmaiden_iam_runtime;
select pg_temp.call(24,'{"action":"remove","gid":"G-TEST25"}');
reset role;
select is((select count(*)::integer from social_private.join_tickets where invite_id=:'remove_invite'),0,'remove cancels accepted unredeemed ticket');
insert into social_private.invites(sender,sender_session,recipient,relay_origin,room_id,owner_id,member_id,generation,expires_at) values(md5('24')::uuid,md5('s24')::uuid,md5('25')::uuid,'https://relay.example.test',repeat('2',32),repeat('3',32),repeat('3',32),1,clock_timestamp()+interval '300 seconds');
set local role gmaiden_iam_runtime;
select pg_temp.call(25,'{"action":"settings","presenceVisible":false,"allowFriendRequests":true,"allowInvites":false}');
reset role;
select is((select count(*)::integer from social_private.invites where recipient=md5('25')::uuid),0,'disabling invites revokes existing incoming invitations');
-- Challenge consumption does not charge a second mutation; only twelve mints per flow minute.
set local role gmaiden_iam_runtime;
select pg_temp.call(26,'{"action":"challenge","purpose":"roster","recipientGid":null,"bindingRevision":null}',repeat('a',63)||'1');
select pg_temp.call(26,'{"action":"roster"}',repeat('a',63)||'1',:'proof');
reset role;
select is((select count from social_private.rate_limits where subject=md5('26')::uuid::text and category='challenge'),1,'challenge mint is the logical flow charge');
select is((select count(*)::integer from social_private.rate_limits where subject=md5('26')::uuid::text and category='mutation'),0,'proof consumption is not charged again');
select * from finish();
rollback;
